parameters.jsCode:
const input = $json.body || $json;
const clean = (v) => String(v ?? '').trim();
const name = clean(input.name);
const email = clean(input.email);
const company = clean(input.company);
const phone = clean(input.phone);
const service = clean(input.service);
const budget = clean(input.budget);
const message = clean(input.message);
const page = clean(input.page || input.sourcePage || $json.headers?.referer);
const utmSource = clean(input.utm_source);
const utmMedium = clean(input.utm_medium);
const utmCampaign = clean(input.utm_campaign);
const ip = clean($json.headers?.['x-forwarded-for'] || $json.headers?.['x-real-ip']);
const userAgent = clean($json.headers?.['user-agent']);
const submittedAt = new Date().toISOString();
const missing = [];
if (!name) missing.push('name');
if (!email) missing.push('email');
if (!message) missing.push('message');
const qualifiedHint = [service, budget, message].join(' ').toLowerCase();
const priority = /urgent|asap|this week|call|automation|seo|website|mobile|crm|lead|booking|pipeline/.test(qualifiedHint) ? 'high' : 'normal';
return [{ json: { name, email, company, phone, service, budget, message, page, utmSource, utmMedium, utmCampaign, ip, userAgent, submittedAt, missing, isValid: missing.length === 0, priority } }];

